"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[43],{18997:e=>{e.exports=JSON.parse('{"tag":{"label":"Edge AI","permalink":"/science/tags/edge-ai","allTagsPath":"/science/tags","count":20,"items":[{"id":"2025/autonomous-camera-control","title":"An Autonomous Camera Control System Inspired by Curiosity","description":"Author: Yufeng Luo, MCS Research Aide, University of Wyoming, Summer 2024","permalink":"/science/2025/autonomous-camera-control"},{"id":"2025/dynamic-data-collection","title":"Application-Agnostic Dynamic Data Collection for AI on the Edge","description":"Henry Abrahamson","permalink":"/science/2025/dynamic-data-collection"},{"id":"2023/bandwidth-aware-learning","title":"Bandwidth Aware Learning","description":"Hi there! My name is Spencer Ng, and I\u2019m a rising second-year studying Computer Science and Theater & Performance Studies at the University of Chicago.","permalink":"/science/2023/bandwidth-aware-learning"},{"id":"2024/finding-events","title":"Creating a System to Find Events in Real Time","description":"Across the United States and the world, the distributed network of Sage nodes captures over 2500 images per day. These nodes have the potential of capturing photos with important features such as smoke, wildlife, and emergencies. Each image contains unique characteristics which, until now, were hard to look for without manually searching through the Sage database. With both the images and users in mind, this project has two goals: harness the power of machine learning to describe photos as they are taken, and build a user-friendly system to allow others to find what they are looking for within our database.","permalink":"/science/2024/finding-events"},{"id":"2026/dangerous-animal-detection","title":"Dangerous Animal Detection and Alerting","description":"Authors: Saurav Koduri (University of Illinois Urbana-Champaign) and Avasyu Chukkapalli (Virginia Tech)","permalink":"/science/2026/dangerous-animal-detection"},{"id":"2026/bat","title":"Edge Acoustic Sensing for Bat Detection","description":"Authors: Jeongmin Chae (University of Southern California) and Julia Gersey (University of Michigan / Argonne National Lab)","permalink":"/science/2026/bat"},{"id":"2024/super-resolution","title":"Exploration of Super Resolution Image Enhancement","description":"Introduction","permalink":"/science/2024/super-resolution"},{"id":"2026/bisonn","title":"Exploring the Potential for Edge Computing to Collect Novel Biotic Interaction Data","description":"Kyle Lima","permalink":"/science/2026/bisonn"},{"id":"2026/image-search-at-the-edge","title":"Image Search at the Edge","description":"Authors: Sajan Neupane (University of Utah) and Pratik Kharade (University of Utah \u2013 SCI Institute)","permalink":"/science/2026/image-search-at-the-edge"},{"id":"2026/flashpoint","title":"Multi-Node Lightning Localization & Wildfire Ignition Watch","description":"Authors: Samuel Watson (University of Hawai\u02bbi at M\u0101noa / HCDP)","permalink":"/science/2026/flashpoint"},{"id":"2026/drought-early-warning","title":"Multimodal Drought Early Warning at the Edge","description":"Authors: Di Fan (University of Florida), Levi Johnson (Colorado State University), John Blackwell (Colorado State University), and Atefeh Hosseini (University of Kansas)","permalink":"/science/2026/drought-early-warning"},{"id":"2026/mortimus-urgent-scheduling","title":"Resilient Urgent Scheduling for Sage","description":"Authors: Dave MacDonald (UC Davis), Sean Huang (University of Chicago), Cl\xe9ment Nunes (Inria), and Morty","permalink":"/science/2026/mortimus-urgent-scheduling"},{"id":"2024/resource-management","title":"Resource Management at the Edge","description":"Abstract","permalink":"/science/2024/resource-management"},{"id":"2026/bat-counter","title":"Sage Bat Counter","description":"Authors: Noah Betoshana (University of California, Davis) and Liam Fitzpatrick (Michigan State University)","permalink":"/science/2026/bat-counter"},{"id":"2026/halow","title":"Sage-HaLow \u2014 First-Pass Summary","description":"Authors: Ben Owusu-Amo and Hairik Honarchian Saki (Colorado State University)","permalink":"/science/2026/halow"},{"id":"2023/scalable-ci-in-aps","title":"Scalable AI@Edge Computing in X-ray Beamline Experiments","description":"Can Edge Computing Be Used in X-Ray Beamline Experiments to Process a High-Volume and Fast Data Stream and Help Scientists Make Real-Time Decisions for Experiments?","permalink":"/science/2023/scalable-ci-in-aps"},{"id":"2024/sound-separation","title":"Sound Separation","description":"By processing data directly at the collection source, edge computing networks like Sage/Waggle offer unique advantages over using centralized servers for ecological monitoring tasks. Audio in particular is useful for tracking metrics like noise pollution from human development or population statistics for vocal wildlife in the area (birds, insects, frogs, etc.). Further analysis can provide deeper insights into the overall health of the ecosystems where nodes are deployed.","permalink":"/science/2024/sound-separation"},{"id":"2026/speech-redaction-at-the-edge","title":"Speech Redaction at the Edge","description":"Miguel Hernandez, Northwestern University","permalink":"/science/2026/speech-redaction-at-the-edge"},{"id":"2025/traffic-counter","title":"Traffic Counting","description":"NOTE: This document is based on the version 1.0.3 of the traffic counter application.","permalink":"/science/2025/traffic-counter"},{"id":"2023/vehicle-tracking","title":"Vehicle Tracking","description":"Hi there!","permalink":"/science/2023/vehicle-tracking"}],"unlisted":false}}')}}]);